// End-to-end: two-step login (Beauty has it on, Health does not), session registry, logout and
// revocation on a copied cookie, panel separation, and the activity log (what it records and what it
// must never contain). Uses throw-away credentials generated by scripts/e2e/run.mjs.
import test, { before, after, beforeEach } from "node:test";
import assert from "node:assert/strict";
import { BASE, launch, state, resetDb, poll, get, apiLogin, freshCode, setFault, clearFaults } from "./helpers.mjs";
import { signSession } from "../../lib/operator/session.js";
import { credentialsVersion } from "../../lib/operator/auth-version.mjs";

const SECRET = process.env.E2E_BEAUTY_TOTP_SECRET;
const RECOVERY = (process.env.E2E_BEAUTY_RECOVERY_CODES || "").split(",");

let browser;
before(async () => { browser = await launch(); });
after(async () => { await browser?.close(); });
beforeEach(async () => { await resetDb(); await clearFaults(); });

const withCookie = (path, cookie, init = {}) => fetch(BASE + path, { redirect: "manual", ...init, headers: { cookie, origin: BASE, ...(init.headers || {}) } });
const audit = async () => (await state()).operator_audit_log;
const isLoggedIn = async (path, cookie) => (await withCookie(path, cookie)).status === 200;

test("Health (no second factor) logs in with the password alone; Beauty asks for a code", async () => {
  const h = await apiLogin("health");
  assert.equal(h.status, 200);
  assert.ok(h.cookie.startsWith("medoria_operator="));
  const b = await apiLogin("beauty");
  assert.equal(b.status, 401);
  assert.equal(b.body.needCode, true, "Beauty must ask for the second factor");
  assert.equal(b.cookie, "", "no cookie before the second factor");
});

test("Beauty two-step login: wrong password, wrong code, right code, replay, recovery codes", async () => {
  const wrongPw = await apiLogin("beauty", { password: "not-it" });
  assert.equal(wrongPw.status, 401);
  assert.ok(!wrongPw.body.needCode, "a wrong password must not reveal that a code is needed");

  const wrongCode = await apiLogin("beauty", { code: "000000" });
  assert.equal(wrongCode.status, 401);
  assert.equal(wrongCode.cookie, "");

  const code = await freshCode(SECRET);
  const ok = await apiLogin("beauty", { code });
  assert.equal(ok.status, 200, JSON.stringify(ok.body));
  assert.ok(await isLoggedIn("/beauty/operator", ok.cookie), "the new Beauty session must open the Beauty panel");

  const replay = await apiLogin("beauty", { code });
  assert.equal(replay.status, 401, "the same code must not work twice");

  const rec = await apiLogin("beauty", { recovery: RECOVERY[0] });
  assert.equal(rec.status, 200);
  assert.equal(rec.body.recoveryUsed, true);
  const recAgain = await apiLogin("beauty", { recovery: RECOVERY[0] });
  assert.equal(recAgain.status, 401, "a recovery code works once");
  const recUnknown = await apiLogin("beauty", { recovery: "AAAA-AAAA-AAAA" });
  assert.equal(recUnknown.status, 401);

  // what the log says about all this, and what it must not say
  const rows = await audit();
  const failed = rows.filter((r) => r.action === "auth.login_failed").map((r) => r.detail?.reason).sort();
  assert.deepEqual(failed, ["bad_code", "bad_code", "password", "recovery_used", "replay"]);
  const logins = rows.filter((r) => r.action === "auth.login").map((r) => r.detail?.method).sort();
  assert.deepEqual(logins, ["password+totp", "recovery"]);
  assert.equal(rows.filter((r) => r.action === "auth.recovery_code_used").length, 1);
  assert.ok(rows.every((r) => r.panel === "beauty"));
  const everything = JSON.stringify(await state());
  for (const secret of [process.env.E2E_BEAUTY_PASSWORD, SECRET, code, ...RECOVERY, "not-it"]) {
    assert.ok(!everything.includes(secret), "a credential or code was stored in the database");
  }
});

test("logout ends the session on the server: a copied cookie stops working", async () => {
  const { cookie } = await apiLogin("health");
  assert.ok(await isLoggedIn("/operator/quotes", cookie));
  const out = await withCookie("/api/operator/logout", cookie, { method: "POST" });
  assert.equal(out.status, 200);
  const after = await withCookie("/operator/quotes", cookie);
  assert.ok(after.status >= 300 && after.status < 400 && /\/login/.test(after.headers.get("location") || ""), `the copied cookie still works after logout (${after.status})`);
  assert.ok((await audit()).some((r) => r.action === "auth.logout" && r.panel === "health"));
});

test("cookies from before the session registry, or for an unknown session, are refused", async () => {
  process.env.OPERATOR_SESSION_SECRET = process.env.E2E_HEALTH_SESSION_SECRET;
  process.env.OPERATOR_USERNAME = process.env.E2E_HEALTH_USER;
  process.env.OPERATOR_PASSWORD_HASH = process.env.E2E_HEALTH_PASSWORD_HASH;
  const ver = credentialsVersion();
  const noSid = await signSession({ role: "admin", ver });
  const unknownSid = await signSession({ role: "admin", ver, sid: "0123456789abcdef01234567" });
  const wrongRole = await signSession({ role: "beauty-admin", ver, sid: "0123456789abcdef01234567" });
  for (const [label, token] of [["no session id", noSid], ["unregistered session id", unknownSid], ["another panel's role", wrongRole]]) {
    const r = await withCookie("/operator", `medoria_operator=${token}`);
    assert.ok(r.status >= 300 && r.status < 400, `${label}: the panel opened (${r.status})`);
  }
});

test("ending other sessions / all sessions works from the settings page, and only for this panel", async () => {
  const ctx = await browser.newContext({ viewport: { width: 1280, height: 900 } });
  const a = await apiLogin("health");
  const b = await apiLogin("health");
  const beauty = await apiLogin("beauty", { code: await freshCode(SECRET) });
  assert.equal(beauty.status, 200);
  const [name, value] = a.cookie.split("=");
  await ctx.addCookies([{ name, value, url: BASE }]);
  const page = await ctx.newPage();
  await page.goto(`${BASE}/operator/settings`, { waitUntil: "networkidle" });
  await page.getByText("این نشست", { exact: true }).waitFor();
  assert.ok((await page.getByText("نشست دیگر", { exact: true }).count()) >= 1, "the other session is not listed");
  assert.ok(!(await page.content()).includes("198.51.100"), "a raw IP address is shown");

  await page.getByRole("button", { name: "پایان نشست‌های دیگر" }).click();
  await page.getByRole("button", { name: "بله" }).click();
  await page.getByText(/نشست دیگر پایان یافت/).waitFor({ timeout: 10000 });
  assert.equal(await isLoggedIn("/operator", b.cookie), false, "the other session survived");
  assert.equal(await isLoggedIn("/operator", a.cookie), true, "this session must survive 'end other sessions'");

  await page.getByRole("button", { name: "پایان همهٔ نشست‌ها" }).click();
  await page.getByRole("button", { name: "بله" }).click();
  await page.waitForURL(/\/login\/health/, { timeout: 10000 });
  assert.equal(await isLoggedIn("/operator", a.cookie), false, "'end all sessions' left a session alive");
  assert.equal(await isLoggedIn("/beauty/operator", beauty.cookie), true, "ending Health sessions must not touch the Beauty panel");
  await ctx.close();
});

test("the activity log records what was done, by session, and never customer data", async () => {
  const ctx = await browser.newContext({ viewport: { width: 1280, height: 900 } });
  const { cookie } = await apiLogin("health");
  const [name, value] = cookie.split("=");
  await ctx.addCookies([{ name, value, url: BASE }]);
  const page = await ctx.newPage();

  await page.goto(`${BASE}/operator/quotes`, { waitUntil: "networkidle" });
  await page.getByLabel("انتخاب E2E Customer 1", { exact: true }).check();
  await page.getByLabel("انتخاب E2E Customer 2", { exact: true }).check();
  await page.getByRole("button", { name: "آرشیو", exact: true }).first().click();
  await page.getByText("2 درخواست به آرشیو منتقل شد.").waitFor({ timeout: 10000 });
  await page.getByRole("tab", { name: /همه/ }).click();
  await page.getByRole("button", { name: "حذف درخواست E2E Customer 3" }).click();
  await page.getByRole("dialog").getByRole("button", { name: "حذف درخواست" }).click();
  await poll(async () => !(await state()).quote_requests.some((q) => q.id === 3), { label: "request 3 deleted" });

  await page.goto(`${BASE}/operator/products`, { waitUntil: "networkidle" });
  const row = page.locator("div", { hasText: "E2E Product 1" }).filter({ has: page.locator('button[title="ویرایش قیمت"]') }).last();
  await row.locator('button[title="ویرایش قیمت"]').click();
  await row.locator('input[type="number"]').fill("12.5");
  await row.locator('input[type="number"]').press("Enter");
  await page.getByText("قیمت ذخیره شد.").waitFor({ timeout: 10000 });

  const rows = await poll(async () => { const r = await audit(); return r.some((x) => x.action === "product.quick") ? r : false; }, { label: "the price change in the log" }).then((p) => p.value);
  const by = (a) => rows.filter((r) => r.action === a);
  const status = by("quote.status")[0];
  assert.deepEqual([status.entity, status.entity_ids.slice().sort(), status.detail], ["quote_requests", [1, 2], { status: "archived" }]);
  const del = by("quote.delete")[0];
  assert.deepEqual([del.entity, del.entity_ids, del.count], ["quote_requests", [3], 1]);
  const price = by("product.quick")[0];
  assert.deepEqual([price.entity, price.entity_ids, price.detail.price, price.detail.fields], ["products", [1], 12.5, ["price"]]);
  assert.ok(rows.every((r) => r.panel === "health" && /^[0-9a-f]{24}$/.test(r.session_id || "") && /^[0-9a-f]{12}$/.test(r.ip_hash || "")), "every entry carries a session id and a hashed network hint");
  const dump = JSON.stringify(await audit());
  for (const pii of ["E2E Customer", "+9929000000", "E2E demo message", "198.51.100", "127.0.0.1"]) assert.ok(!dump.includes(pii), `the log contains ${pii}`);

  // and the person looking at it sees plain labels, no customer data
  await page.goto(`${BASE}/operator/activity`, { waitUntil: "networkidle" });
  for (const label of ["حذف درخواست", "تغییر وضعیت درخواست", "ویرایش سریع محصول"]) await page.getByText(label).first().waitFor();
  const text = await page.locator("main").innerText();
  assert.ok(!text.includes("E2E Customer") && !text.includes("+9929"), "customer data on the activity page");
  await ctx.close();
});

test("a deletion is refused while the log cannot be written AND when the log table does not exist (a missing history is never a permission)", async () => {
  const ctx = await browser.newContext({ viewport: { width: 1280, height: 900 } });
  const { cookie } = await apiLogin("health");
  const [name, value] = cookie.split("=");
  await ctx.addCookies([{ name, value, url: BASE }]);
  const page = await ctx.newPage();
  await page.goto(`${BASE}/operator/quotes`, { waitUntil: "networkidle" });
  await page.getByRole("tab", { name: /همه/ }).click();

  await setFault("operator_audit_log", "POST", 500, "XX000");       // the log is broken
  await page.getByRole("button", { name: "حذف درخواست E2E Customer 3" }).click();
  await page.getByRole("dialog").getByRole("button", { name: "حذف درخواست" }).click();
  await page.getByRole("alert").getByText(/ثبت در تاریخچه ممکن نشد/).waitFor({ timeout: 10000 });
  assert.ok((await state()).quote_requests.some((q) => q.id === 3), "the request was deleted although the log could not be written");
  await page.getByRole("dialog").getByRole("button", { name: "انصراف" }).click();

  await clearFaults();
  await setFault("operator_audit_log", "POST", 404, "PGRST205");    // the table does not exist (migration 30 not applied)
  await page.getByRole("button", { name: "حذف درخواست E2E Customer 3" }).click();
  await page.getByRole("dialog").getByRole("button", { name: "حذف درخواست" }).click();
  await page.getByRole("alert").getByText(/تاریخچهٔ فعالیت در دسترس نیست/).waitFor({ timeout: 10000 });
  assert.ok((await state()).quote_requests.some((q) => q.id === 3), "the request was deleted although there is no log table");
  await page.getByRole("dialog").getByRole("button", { name: "انصراف" }).click();

  await clearFaults();                                                // the log works again: the deletion goes through, with attempt and outcome on record
  await page.getByRole("button", { name: "حذف درخواست E2E Customer 3" }).click();
  await page.getByRole("dialog").getByRole("button", { name: "حذف درخواست" }).click();
  await poll(async () => !(await state()).quote_requests.some((q) => q.id === 3), { label: "deletion with a working log" });
  const trail = (await state()).operator_audit_log.filter((r) => /^quote\.delete/.test(r.action)).sort((a, b) => a.id - b.id).map((r) => r.action);
  assert.deepEqual(trail, ["quote.delete_attempt", "quote.delete"]);
  await ctx.close();
});
